<body>
  <main class="wrap">
    <h1>Pocket Garden</h1>
    <p class="lead">Pick a spot for your plants and mark what you've planted.</p>
    <p class="notice"><strong>Note:</strong> your choices reset when you reload this page.</p>

    <fieldset class="filters" id="filters">
      <legend>Filter plants</legend>
      <button type="button" data-filter="all" aria-pressed="true">All plants</button>
      <button type="button" data-filter="sun" aria-pressed="false">Loves sun</button>
      <button type="button" data-filter="shade" aria-pressed="false">Likes shade</button>
    </fieldset>

    <p class="status" id="status" role="status" aria-live="polite"></p>

    <ul class="grid" id="grid">
      <li class="card" data-light="sun">
        <span class="icon" aria-hidden="true">🌿</span>
        <h2 id="name-basil">Basil</h2>
        <span class="tag sun">Loves sun</span>
        <p>Needs warm, bright days. Pinch the tips to keep it bushy.</p>
        <button type="button" class="plant-btn" aria-describedby="name-basil">Mark as planted</button>
      </li>
      <li class="card" data-light="sun">
        <span class="icon" aria-hidden="true">🌻</span>
        <h2 id="name-sunflower">Sunflower</h2>
        <span class="tag sun">Loves sun</span>
        <p>Grows tall in full sun. Give it space and a sturdy support.</p>
        <button type="button" class="plant-btn" aria-describedby="name-sunflower">Mark as planted</button>
      </li>
      <li class="card" data-light="shade">
        <span class="icon" aria-hidden="true">🍃</span>
        <h2 id="name-mint">Mint</h2>
        <span class="tag shade">Likes shade</span>
        <p>Happy in cool, shaded corners. Keep it in a pot so it can't spread.</p>
        <button type="button" class="plant-btn" aria-describedby="name-mint">Mark as planted</button>
      </li>
    </ul>
  </main>

<script>
(function () {
  var filterButtons = document.querySelectorAll('#filters button');
  var cards = document.querySelectorAll('.card');
  var status = document.getElementById('status');
  var labels = { all: 'all plants', sun: 'plants that love sun', shade: 'plants that like shade' };

  function applyFilter(name) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = name === 'all' || card.dataset.light === name;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.dataset.filter === name));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' — ' + labels[name] + '.';
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
  });

  cards.forEach(function (card) {
    var btn = card.querySelector('.plant-btn');
    btn.addEventListener('click', function () {
      var planted = !card.classList.contains('is-planted');
      card.classList.toggle('is-planted', planted);
      btn.classList.toggle('planted', planted);
      btn.textContent = planted ? 'Planted' : 'Mark as planted';
    });
  });

  applyFilter('all');
})();
</script>
</body>
